// closure_agent.oracle — semantic conformance against the frozen Python
// product verdicts (agent_oracle.json, generated by
// libs/closure_agent/oracle/generate_agent_oracle.py from the real Python
// tree; see the line-11 ledger for the Python SHA).
#include "test_util.hpp"

#include <pwb/closure_agent/context.hpp>
#include <pwb/closure_agent/intent.hpp>
#include <pwb/closure_agent/planner.hpp>
#include <pwb/closure_agent/registry.hpp>
#include <pwb/closure_agent/spec.hpp>

#include <cmath>
#include <fstream>
#include <sstream>

using namespace pwb::closure_agent;

namespace {

Json load_fixture() {
    const char* path = PWB_CLOSURE_AGENT_FIXTURE;
    std::ifstream in(path, std::ios::binary);
    if (!in) throw std::runtime_error(std::string("fixture missing: ") + path);
    std::ostringstream buffer;
    buffer << in.rdbuf();
    return Json::parse(buffer.str());
}

ActionSpec make_oracle_spec(const std::string& name) {
    // Mirrors SPECS in the generator (handler absent -> executable problem).
    ActionSpec spec;
    spec.description = "x";
    if (name == "ok_compute") {
        spec.action_id = "well.correlate_tops";
        spec.risk = ActionRisk::Compute;
        spec.version = "1.2";
        spec.deterministic = true;
        spec.cacheable = true;
        spec.output_refs = {"PathRef"};
        spec.domain_tags = {"well", "correlation"};
    } else if (name == "bad_id") {
        spec.action_id = "Bad-ID";
    } else if (name == "bad_cacheable") {
        spec.action_id = "map.export";
        spec.cacheable = true;
    } else if (name == "bad_version") {
        spec.action_id = "map.export";
        spec.version = "v1";
    } else if (name == "no_executable") {
        spec.action_id = "map.export";
    } else if (name == "bad_tag") {
        spec.action_id = "map.export";
        spec.domain_tags = {"Bad Tag"};
    } else {  // destructive
        spec.action_id = "map.purge";
        spec.risk = ActionRisk::Destructive;
    }
    return spec;
}

void check_intents(const Json& oracle) {
    IntentParser parser;
    for (const auto& record : oracle["intents"]) {
        const std::string query = record["query"].get<std::string>();
        const ParsedIntent intent = parser.parse(query);
        const std::string label = "intent[" + query + "]";
        check(intent.raw_query == record["raw_query"].get<std::string>(),
              label + " raw_query");
        check(to_string(intent.primary_domain) ==
                  record["primary_domain"].get<std::string>(),
              label + " primary_domain");
        std::vector<std::string> secondary;
        for (const auto domain : intent.secondary_domains) {
            secondary.push_back(to_string(domain));
        }
        check(secondary == record["secondary_domains"].get<std::vector<std::string>>(),
              label + " secondary_domains");
        check(intent.target_horizon == record["target_horizon"].get<std::string>(),
              label + " target_horizon");
        check(intent.factor_type == record["factor_type"].get<std::string>(),
              label + " factor_type");
        check(intent.suggested_skills ==
                  record["suggested_skills"].get<std::vector<std::string>>(),
              label + " suggested_skills");
        check(intent.requires_data == record["requires_data"].get<bool>(),
              label + " requires_data");
        check(std::abs(intent.confidence -
                       record["confidence"].get<double>()) < 1e-9,
              label + " confidence");
    }
}

void check_plans(const Json& oracle) {
    IntentParser parser;
    TaskPlanner planner;
    for (const auto& record : oracle["plans"]) {
        const ParsedIntent intent = parser.parse(record["query"].get<std::string>());
        const TaskGraph graph = planner.create_plan(intent);
        const Json& expected = record["nodes"];
        bool order_and_shape_ok = graph.nodes.size() == expected.size();
        if (order_and_shape_ok) {
            for (std::size_t i = 0; i < graph.nodes.size(); ++i) {
                const TaskNode& node = graph.nodes[i];
                const Json& want = expected[i];
                if (node.id != want["id"].get<std::string>() ||
                    node.agent_name != want["agent_name"].get<std::string>() ||
                    node.action != want["action"].get<std::string>() ||
                    node.dependencies !=
                        want["dependencies"].get<std::vector<std::string>>()) {
                    order_and_shape_ok = false;
                    break;
                }
            }
        }
        check(order_and_shape_ok,
              "plan skeleton for [" + record["query"].get<std::string>() + "]");
    }
}

void check_spec_validation(const Json& oracle) {
    for (const auto& record : oracle["spec_validation"]) {
        const ActionSpec spec = make_oracle_spec(record["name"].get<std::string>());
        const auto problems = validate_action_spec(spec);
        check(problems == record["problems"].get<std::vector<std::string>>(),
              "spec problems for " + record["name"].get<std::string>());
    }
}

void check_tool_schema(const Json& oracle) {
    ActionSpec spec;
    spec.action_id = "geology.factor_summary";
    spec.description = "Summarize a factor dataset";
    spec.provider_id = "geology.factor_stats";
    spec.input_schema = Json::object();
    spec.input_schema["type"] = "object";
    Json report_name = Json::object();
    report_name["type"] = "string";
    report_name["description"] = "报告工件名";
    spec.input_schema["properties"] = Json::object();
    spec.input_schema["properties"]["report_name"] = report_name;
    spec.input_schema["required"] = std::vector<std::string>{"report_name"};
    spec.input_schema["additionalProperties"] = false;
    check(spec.tool_schema() == oracle["tool_schema"],
          "derived tool_schema matches the frozen Python projection");
}

void check_default_permissions(const Json& oracle) {
    std::vector<std::string> names;
    for (const auto risk : default_permissions()) names.push_back(to_string(risk));
    std::sort(names.begin(), names.end());
    check(names == oracle["default_permissions"].get<std::vector<std::string>>(),
          "default permissions = {read, compute}");
}

}  // namespace

int main() {
    try {
        const Json oracle = load_fixture();
        check_intents(oracle);
        check_plans(oracle);
        check_spec_validation(oracle);
        check_tool_schema(oracle);
        check_default_permissions(oracle);
    } catch (const std::exception& exc) {
        std::fprintf(stderr, "FATAL %s\n", exc.what());
        return 1;
    }
    return test_exit("closure_agent.oracle");
}
